contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger) public {
        require(logger != address(0), "logger must be nonzero");

        // Owner (this contract) approves logger.
        c.setApprovedLogger(logger, true);

        // Before state: logger is approved.
        bool approvedBefore = c.approvedToLog(logger);
        require(approvedBefore, "logger should be approved after setApprovedLogger");

        // The rule only concerns what we can observe after a state change
        // through the public surface. We verify that the approval actually
        // took effect and that a subsequent log* call from the logger
        // succeeds (returns true) and does not revert.
        //
        // We make a top-level call to one log function. All log functions
        // behave identically with respect to approvedToLog, so one
        // representative is enough for a general rule about approval.
        bool logSucceeded;
        try c.logFunded() {
            logSucceeded = true;
        } catch {
            logSucceeded = false;
        }

        // General rule: once a logger is approved, the logger's calls to log*
        // return true and do not revert, and the approval remains readable.
        assert(logSucceeded && c.approvedToLog(logger));
    }

    receive() external payable {}
}

