contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger, bool toggle) public {
        // Owner approves the logger. If toggle is true, also try setting it back to true,
        // exercising the setter on an already-approved logger.
        c.setApprovedLogger(logger, true);
        if (toggle) {
            c.setApprovedLogger(logger, true);
        }

        // Read approval status through the public getter.
        bool approvedAfter = c.approvedToLog(logger);

        // Call a log function as the approved logger. Use try/catch to capture revert and return value.
        bool reverted;
        bool returnedTrue;
        try c.logFunded() returns (bool result) {
            reverted = false;
            returnedTrue = result;
        } catch {
            reverted = true;
            returnedTrue = false;
        }

        // General rule: when approved, the logger remains approved and a log* call must not revert and must return true.
        assert(approvedAfter && !reverted && returnedTrue && c.approvedToLog(logger));
    }

    receive() external payable {}
}

