contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger, bytes32 txid) public {
        // Ensure logger is not approved before the call.
        bool wasApproved = c.approvedToLog(logger);
        // If logger is already approved, the rule is trivially satisfied for this input.
        // But we want to test the unapproved case; we cannot call setApprovedLogger with false
        // because that requires owner and would make the rule about false approval meaningless.
        // So we only assert when logger is initially unapproved.
        if (!wasApproved) {
            bool success = c.logRedeemed(txid);
            bool stillApproved = c.approvedToLog(logger);
            assert(!success && !stillApproved);
        } else {
            assert(wasApproved);
        }
