    }

    function run(address logger, bool status) public {
        // Ensure the target address is valid and the owner deploys this test, so msg.sender is the owner.
        require(logger != address(0));

        // Record before state (logger is unapproved by default in a fresh contract).
        bool before = c.approvedToLog(logger);

        // Owner-approved logger status change.
        c.setApprovedLogger(logger, status);

        // The general rule: after setting approval status to true, approvedToLog must be true.
